@@ -0,0 +1,121 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+async function receiveToAnnex(handle, lots) {
+  const lines = lots.map((l) => ({ itemId: l.itemId, qty: l.qty }));
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return (await handle({
+    method: "POST",
+    path: `/orders/${order.id}/receive`,
+    headers: ANNEX,
+    body: { lots: lots.map((l) => ({ lot: l.lot, expires: l.expires ?? null, location: "annex-fridge" })) },
+  })).body.batches;
+}
+
+test("seed has main and annex sites and annex-fridge location", async () => {
+  const { store } = app();
+  assert.equal(store.data.schemaVersion, 3);
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), {
+    id: "annex-fridge",
+    name: "Annex fridge",
+    tempC: 4,
+    site: "annex",
+  });
+});
+
+test("unknown X-Larder-Site returns 400 with unknown_site error code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "rooftop" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /rooftop/);
+});
+
+test("batches and stock on hand are isolated by site while items, suppliers, recipes and dishes are shared", async () => {
+  const { handle } = app();
+
+  // Items, suppliers, recipes/costing and dishes are shared on annex.
+  const annexItems = await handle({ path: "/items", headers: ANNEX });
+  assert.equal(annexItems.status, 200);
+  assert.equal(annexItems.body.length, 6);
+  assert.ok(annexItems.body.every((i) => i.onHand === 0));
+  assert.equal((await handle({ path: "/suppliers", headers: ANNEX })).body.length, 2);
+  assert.equal((await handle({ path: "/dishes", headers: ANNEX })).body.length, 3);
+  assert.equal((await handle({ path: "/recipes/1/cost", headers: ANNEX })).status, 200);
+
+  // Annex initially sees no batches.
+  assert.deepEqual((await handle({ path: "/batches", headers: ANNEX })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } })).status, 404);
+
+  // Receiving a batch into annex-fridge makes it visible only on annex.
+  const [batch] = await receiveToAnnex(handle, [{ itemId: 1, qty: 3, lot: "ANX-1", expires: "2026-10-30" }]);
+  assert.equal((await handle({ path: "/items/1", headers: ANNEX })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1", headers: ANNEX })).body.batches.length, 1);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: `/batches/${batch.id}`, headers: ANNEX })).status, 200);
+});
+
+test("cooking, alerts and stock value report only see the request's site", async () => {
+  const { handle, store } = app();
+
+  // Annex cannot cook recipe 2 when stock is only in main.
+  const fail = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(fail.status, 409);
+  assert.equal(fail.body.error.code, "not_enough_stock");
+
+  // Stock annex with recipe 2 ingredients and cook 5 portions (half recipe: 1l milk, 0.1kg butter, 0.1kg flour).
+  await receiveToAnnex(handle, [
+    { itemId: 2, qty: 2, lot: "ANX-M", expires: "2026-10-30" },
+    { itemId: 3, qty: 1, lot: "ANX-B", expires: "2026-12-01" },
+    { itemId: 4, qty: 5, lot: "ANX-F", expires: "2027-01-01" },
+  ]);
+  const mainMilkBefore = (await handle({ path: "/items/2" })).body.onHand;
+  const cooked = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 5 } });
+  assert.equal(cooked.status, 200);
+  assert.equal((await handle({ path: "/items/2", headers: ANNEX })).body.onHand, 1);
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, mainMilkBefore);
+
+  // Alerts only see the request's site.
+  const mainAlerts = (await handle({ path: "/alerts" })).body;
+  const annexAlerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.ok(mainAlerts.expiring.every((b) => b.location !== "annex-fridge"));
+  assert.ok(annexAlerts.expiring.every((b) => b.location === "annex-fridge"));
+  assert.ok(annexAlerts.expiring.some((b) => b.lot === "ANX-M"));
+  assert.ok(!mainAlerts.expiring.some((b) => b.lot === "ANX-M"));
+  assert.ok(annexAlerts.lowStock.some((i) => i.name === "flour"));
+  assert.ok(!mainAlerts.lowStock.some((i) => i.name === "flour"));
+
+  // Stock value report only sees the request's site.
+  const mainValue = (await handle({ path: "/reports/stock-value" })).body;
+  const annexValue = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(annexValue.totalCents, Math.round(1 * 129 + 0.9 * 945 + 4.9 * 85));
+  assert.notEqual(mainValue.totalCents, annexValue.totalCents);
+  assert.equal(store.data.batches.some((b) => b.location === "annex-fridge"), true);
+});
+
+test("stock-takes are scoped to the request's site", async () => {
+  const { handle } = app();
+  const [batch] = await receiveToAnnex(handle, [{ itemId: 2, qty: 4, lot: "ANX-ST" }]);
+
+  // Cannot start a stock-take for another site's location.
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "fridge" } })).status, 400);
+
+  // Annex stock-take cannot be accessed from main, and works on annex.
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 3 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+
+  const counted = await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: batch.id, counted: 3 } });
+  assert.equal(counted.status, 200);
+  const finished = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.equal(finished.status, 200);
+  assert.deepEqual(finished.body.lines, [{ batchId: batch.id, expected: 4, counted: 3, diff: -1 }]);
+});
